// ===========================================================================
//  Match Old HTML Folders
//  For every sheet row whose slide folder still has NO carousel_post<N>.html,
//  look for an HTML file saved earlier in an old-style folder
//  (<surname>_<title>_<variant>_<driveId6>, optionally with a timestamp prefix)
//  and check it belongs to the SAME run as the slides now in the folder.
//
//  Verification, strongest first:
//   verified_same_run   the old folder's slide JPGs are byte-identical to the
//                       ones in the destination folder, so it is the same run
//   different_run       old folder has JPGs but they differ: an older version
//   unverified_close    no JPGs to compare; HTML file saved within
//                       MAX_HOURS of the row's generated_at
//   unverified_far      no JPGs; saved long before/after the row was generated
//  Only verified_same_run is copied, unless COPY_UNVERIFIED_CLOSE is on.
// ===========================================================================

const fs = require('fs');
const path = require('path');

const s = $('Settings').first().json;
const DRY = s.DRY_RUN !== false;
const COPY_CLOSE = s.COPY_UNVERIFIED_CLOSE === true;
const MAX_HOURS = Number(s.MAX_HOURS || 6);
const SLIDES_ROOT = String(s.SLIDES_ROOT).replace(/[\\/]+$/, '');
const OLD_ROOTS = String(s.OLD_HTML_ROOTS).split(',').map((d) => d.trim()).filter(Boolean);

// Byte-for-byte comparison without the crypto module: size first, then contents.
function sameAsAny(file, others) {
  const size = fs.statSync(file).size;
  const same = others.filter((o) => o.size === size);
  if (!same.length) return false;
  const buf = fs.readFileSync(file);
  return same.some((o) => buf.equals(fs.readFileSync(o.path)));
}
const jpgs = (dir) => fs.readdirSync(dir).filter((f) => /\.jpe?g$/i.test(f)).sort();
const htmls = (dir) => fs.readdirSync(dir).filter((f) => /\.html?$/i.test(f));
const stripPrefix = (name) => name.replace(/^\d{10,}_/, '');   // "1790755131927_Dameski_..." -> "Dameski_..."

function walkDirs(root, maxDepth) {
  const out = new Map();   // folder name -> [full paths]
  (function walk(d, depth) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      if (!e.isDirectory() || e.name.startsWith('.')) continue;
      const full = path.join(d, e.name);
      if (!out.has(e.name)) out.set(e.name, []);
      out.get(e.name).push(full);
      if (depth < maxDepth) walk(full, depth + 1);
    }
  })(root, 1);
  return out;
}

// --- old folders that contain HTML -----------------------------------------
// Indexed two ways: by old folder name, and by "<driveId6>_<variant>".
const oldByName = new Map();
const oldById = new Map();
for (const root of OLD_ROOTS) {
  if (!fs.existsSync(root)) throw new Error(`OLD_HTML_ROOTS entry does not exist: ${root}`);
  for (const [name, paths] of walkDirs(root, 3)) {
    for (const p of paths) {
      const hs = htmls(p);
      if (!hs.length) continue;
      // Newest HTML in the folder, if there are several.
      const pick = hs.map((f) => ({ f, t: fs.statSync(path.join(p, f)).mtimeMs })).sort((a, b) => b.t - a.t)[0];
      const rec = { dir: p, html: path.join(p, pick.f), htmlCount: hs.length, mtime: pick.t, name: stripPrefix(name) };
      const push = (m, k) => { if (!m.has(k)) m.set(k, []); m.get(k).push(rec); };
      push(oldByName, rec.name);
      const m = rec.name.match(/_(applied|research|[a-z]+)_([A-Za-z0-9_-]{6})$/);
      if (m) push(oldById, `${m[2]}_${m[1]}`);
    }
  }
}

// --- current slide folders ---------------------------------------------------
if (!fs.existsSync(SLIDES_ROOT)) throw new Error(`SLIDES_ROOT does not exist: ${SLIDES_ROOT}`);
const slideDirs = walkDirs(SLIDES_ROOT, 3);

// --- sheet rows ----------------------------------------------------------------
const groups = new Map();
for (const r of $input.all().map((i) => i.json)) {
  if (!r.row_key || /^FIRST FILE LINE/i.test(String(r.row_key))) continue;
  const k = String(r.row_key).trim();
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(r);
}

const results = [];
for (const [key, rs] of groups) {
  rs.sort((a, b) => String(b.generated_at || '').localeCompare(String(a.generated_at || '')));
  const row = rs.find((r) => slideDirs.has(String(r.folder_name || '').trim())) || rs[0];
  const folderName = String(row.folder_name || '').trim();
  const oldFolder = (String(row.notes || '').match(/Local folder:\s*(\S+)/) || [])[1] || '';
  const n = Number(row.post_index) || Number(key.split('_').pop()) || 1;
  const out = { row_key: key, folder_name: folderName, old_folder: oldFolder, title: row.title };

  const dests = slideDirs.get(folderName) || (oldFolder && slideDirs.get(oldFolder)) || [];
  if (dests.length !== 1) { results.push({ ...out, status: dests.length ? 'dest_ambiguous' : 'dest_not_found' }); continue; }
  const dest = dests[0];
  const destHtml = path.join(dest, `carousel_post${n}.html`);
  if (fs.existsSync(destHtml)) continue;   // already has HTML, nothing to do

  // Candidate old folders: by exact old name, else by drive id + variant.
  const variant = String(row.variant || key.split('_').slice(-2, -1)[0] || '');
  let cands = (oldFolder && oldByName.get(oldFolder)) || [];
  if (!cands.length) cands = oldById.get(`${String(row.drive_file_id || key).slice(0, 6)}_${variant}`) || [];
  cands = cands.filter((c) => path.resolve(c.dir) !== path.resolve(dest));
  if (!cands.length) { results.push({ ...out, status: 'no_old_html_found' }); continue; }

  // Check each candidate, keep the best.
  const destJ = jpgs(dest);
  const genAt = Date.parse(row.generated_at || '') || null;
  const rank = { verified_same_run: 0, unverified_close: 1, unverified_far: 2, different_run: 3 };
  let best = null;
  for (const c of cands) {
    const oldJ = jpgs(c.dir);
    let status;
    let detail;
    if (oldJ.length && destJ.length) {
      const oldFiles = oldJ.map((f) => {
        const p = path.join(c.dir, f);
        return { path: p, size: fs.statSync(p).size };
      });
      const shared = destJ.filter((f) => sameAsAny(path.join(dest, f), oldFiles)).length;
      status = shared === destJ.length && oldJ.length === destJ.length ? 'verified_same_run' : 'different_run';
      detail = `${shared}/${destJ.length} slide images identical`;
    } else {
      const hrs = genAt ? Math.abs(c.mtime - genAt) / 36e5 : null;
      status = hrs !== null && hrs <= MAX_HOURS ? 'unverified_close' : 'unverified_far';
      detail = hrs === null ? 'no generated_at in sheet' : `HTML saved ${hrs.toFixed(1)} h from generated_at`;
    }
    const cand = { ...c, status, detail };
    if (!best || rank[status] < rank[best.status]) best = cand;
  }

  const r = { ...out, status: best.status, detail: best.detail, source: best.html, destination: destHtml,
    candidates: cands.length, html_files_in_old_folder: best.htmlCount };

  const ok = best.status === 'verified_same_run' || (COPY_CLOSE && best.status === 'unverified_close');
  if (ok) {
    if (DRY) r.action = 'would_copy';
    else { fs.copyFileSync(best.html, destHtml); r.action = 'copied'; }
  } else r.action = 'skipped';
  results.push(r);
}

const count = (f) => results.reduce((m, r) => ((m[r[f]] = (m[r[f]] || 0) + 1), m), {});
const summary = {
  row_key: '_SUMMARY', dry_run: DRY,
  rows_still_missing_html: results.length,
  old_folders_with_html: [...oldByName.values()].reduce((a, v) => a + v.length, 0),
  by_status: count('status'), by_action: count('action'),
};
const reportPath = path.join(String(s.REPORT_DIR || '/files/_recovery'), 'old_html_match_report.json');
fs.mkdirSync(path.dirname(reportPath), { recursive: true });
fs.writeFileSync(reportPath, JSON.stringify({ summary, results }, null, 2), 'utf8');
summary.report = reportPath;

return [summary, ...results].map((j) => ({ json: j }));
